import (
	"archive/tar"
	"compress/gzip"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

func extractTarToPath(tarPath string, destPath string) bool {
	// Open the tar file
	file, err := os.Open(tarPath)
	if err != nil {
		return false
	}
	defer file.Close()

	// Check if the file is a gzip compressed tar file
	reader, err := gzip.NewReader(file)
	if err != nil {
		return false
	}
	defer reader.Close()

	// Create a tar reader
	tarReader := tar.NewReader(reader)

	// Walk through the tar file entries
	for {
		header, err := tarReader.Next()
		if err == io.EOF {
			break // End of archive
		}
		if err != nil {
			return false
		}

		// Get the file name from the header
		path := header.Name

		// Validate the path to prevent directory traversal attacks
		fullPath := filepath.Join(destPath, path)
		if !filepath.IsAbs(fullPath) && !strings.HasPrefix(fullPath, destPath+string(os.PathSeparator)) {
			continue
		}

		// Check if the path is within the destination directory
		if filepath.Dir(fullPath) != destPath && !filepath.IsAbs(fullPath) {
			continue
		}

		// Skip if the path is a symlink pointing outside the destination
		if header.Typeflag == tar.TypeSymlink {
			target, _ := os.Readlink(path)
			if !strings.HasPrefix(target, destPath) {
				continue
			}
		}

		// Create the directory if it doesn't exist
		if header.Typeflag == tar.TypeDir {
			if err := os.MkdirAll(fullPath, 0700); err != nil {
				return false
			}
			continue
		}

		// Create the file
		filePath := fullPath
		file, err = os.OpenFile(filePath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, os.FileMode(header.Mode))
		if err != nil {
			return false
		}
		defer file.Close()

		// Copy the file contents
		if _, err := io.Copy(file, tarReader); err != nil {
			return false
		}
	}

	return true
}
